a<-commandArgs(TRUE);if(length(a)<3)stop("Usage: train_gbm.R <dev> <val> <out> [vars] [seed]");if(!requireNamespace("gbm",quietly=TRUE)||!requireNamespace("survival",quietly=TRUE))stop("Install gbm and survival");tr<-read.csv(a[1],check.names=FALSE);va<-read.csv(a[2],check.names=FALSE);out<-a[3];v<-if(length(a)>=4)strsplit(a[4],",",TRUE)[[1]]else setdiff(names(tr),c("Time","Event"));seed<-if(length(a)>=5)as.integer(a[5])else 123L;dir.create(out,recursive=TRUE,showWarnings=FALSE);set.seed(seed);f<-as.formula(paste("survival::Surv(Time,Event)~",paste(v,collapse="+")));fit<-gbm::gbm(f,tr,distribution="coxph",n.trees=3000,interaction.depth=5,n.minobsinnode=3,shrinkage=.01,cv.folds=10,n.cores=1,verbose=FALSE);best<-gbm::gbm.perf(fit,method="cv",plot.it=FALSE);for(nm in c("development","validation")){d<-if(nm=="development")tr else va;write.csv(data.frame(Time=d$Time,Event=d$Event,GBM=as.numeric(predict(fit,d,n.trees=best,type="link"))),file.path(out,paste0(nm,"_gbm_predictions.csv")),row.names=FALSE)};saveRDS(list(model=fit,best_trees=best,predictors=v),file.path(out,"gbm_model.rds"))
